# One workflow, compiled for the WSTC Dagster. Assets (all under __ME__/__WF__/):
#   <slot>/<source>/<step>   one per input step: LANDFIRE, roads override, wind, moisture, ignitions
#   reference/<block>        the observed perimeter, rasterized onto the case grid
#   prediction               partitioned: one partition per run (model x params x input choices)
#   score/<metric>           partitioned like prediction
#   report                   every finished run's scores in one table
#
# How a step runs: its pod starts from its block's image (IMAGES), writes the blocks' code
# (CODE) to /tmp, runs the block on a step.json / run.json, checks what it wrote against the
# conventions, and only then moves the artifact into place under its identity on the shared
# volume. A step whose identity already holds a finished artifact reuses it instead.
#
# This file only imports dagster and the standard library: the code server that loads it
# runs the server's standard image, without the blocks' packages.
import base64
import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

import dagster as dg

ME = "__ME__"
WF = "__WF__"
IMAGES = __IMAGES__              # {image family: image reference}
PLAN = json.loads(__PLAN__)      # bench.wstc.compile_plan(...)
REFERENCE_GEOJSON = __REFERENCE__
CODE = __CODE__                  # {file name: source} of the blocks the plan uses + conventions + previews

# TEMP(shared-volume): the artifact store. Kai: not backed up, 10 GiB shared by everyone;
# finished artifacts move to the S3 bucket (wstc-dagster) next, under the same identity paths.
ART = Path(f"/opt/dagster/shared/storage/{ME}/bench/artifacts")
CODE_DIR = Path("/tmp/bench/code")
GROUP = f"{ME}_{WF}"
RUN_KEYS = sorted(PLAN["runs"])
RUNS_PART = dg.StaticPartitionsDefinition(RUN_KEYS)
TAG_EMAIL = "bench/lfps_email"   # run tag carrying the email LANDFIRE's service requires


def _pod(image_family: str, resources: dict) -> dict:
    """op_tags for a step: start its pod from its block's image, with its block's resources
    (Kubernetes requests/limits, from the manifest; bench.wstc.k8s_resources)."""
    return {"dagster-k8s/config": {"container_config": {"image": IMAGES[image_family],
                                                        "resources": resources}}}


# --------------------------------------------------------------------------- #
# running code inside the step's pod
# --------------------------------------------------------------------------- #
def _python_env(extra: dict | None = None) -> dict:
    """Environment for block subprocesses: the shipped code on the path, the artifact root."""
    CODE_DIR.mkdir(parents=True, exist_ok=True)
    for name, text in CODE.items():
        (CODE_DIR / name).write_text(text)
    return {**os.environ, "PYTHONPATH": str(CODE_DIR), "BENCH_ARTIFACT_ROOT": str(ART),
            "MPLCONFIGDIR": "/tmp/bench/mpl", "PYTHONUNBUFFERED": "1", **(extra or {})}


def _run(context, script: str, *args, extra_env: dict | None = None) -> None:
    """Run one of the shipped scripts with the image's Python, streaming its output to the
    Dagster log. A non-zero exit fails the step, with the last lines of output attached."""
    t = time.time()
    proc = subprocess.Popen([sys.executable, str(CODE_DIR / script), *map(str, args)],
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                            env=_python_env(extra_env))
    tail = []
    for line in proc.stdout:
        line = line.rstrip()
        tail = (tail + [line])[-60:]
        if line and not line.startswith((" ", "{", "}", "]", "[")):     # skip pretty-printed JSON
            context.log.info(f"[{Path(script).stem}] {line[:400]}")
    if proc.wait() != 0:
        raise dg.Failure(f"{script} failed after {time.time() - t:.0f}s", metadata={"output": "\n".join(tail)})


def _check_conventions(context, artifact: Path) -> None:
    """Every raster a block wrote must follow docs/conventions.md (grid, orientation, CRS,
    units). Checked before the artifact is accepted, so no step ever reads a bad one."""
    case_file = artifact.parent / f"{artifact.name}.case.json"
    case_file.write_text(json.dumps(PLAN["case"]))
    try:
        _run(context, "conventions.py", artifact, case_file)
    except dg.Failure as e:
        raise dg.Failure(f"{artifact.name}: breaks the conventions (docs/conventions.md)",
                         metadata=e.metadata) from None
    finally:
        case_file.unlink(missing_ok=True)


# --------------------------------------------------------------------------- #
# the artifact store: identity paths, reuse, atomic writes
# --------------------------------------------------------------------------- #
def _done(path: str) -> dict | None:
    """The finished-marker of the artifact at `path` (its summary and who built it), if any."""
    marker = ART / path / "_done.json"
    return json.loads(marker.read_text()) if marker.exists() else None


def _materialize(context, path: str, build) -> tuple[dict, bool]:
    """Build the artifact at its identity path unless it is already there.

    Returns (done marker, reused). `build(tmp)` writes into a temporary sibling; the result
    is checked and then renamed into place, so a reader never sees half an artifact and a
    failed step leaves nothing behind that looks finished."""
    if done := _done(path):
        context.log.info(f"reused {path} (built {done.get('finished_utc')} by run {done.get('run_id', '?')[:8]})")
        return done, True
    final = ART / path
    tmp = ART / f"{path}.tmp-{context.run_id[:8]}"
    shutil.rmtree(tmp, ignore_errors=True)
    tmp.mkdir(parents=True)
    t = time.time()
    try:
        summary = build(tmp) or {}
        _check_conventions(context, tmp)
    except BaseException:
        shutil.rmtree(tmp, ignore_errors=True)
        raise
    done = {"summary": summary, "seconds": round(time.time() - t, 1), "run_id": context.run_id,
            "finished_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
    (tmp / "_done.json").write_text(json.dumps(done, default=str))
    if final.exists():                      # an unfinished leftover (no _done.json): replace it
        shutil.rmtree(final)
    os.replace(tmp, final)
    return done, False


def _run_step(context, script: str, step: dict, tmp: Path, extra_env: dict | None = None) -> dict:
    """Run a core block on its step.json (docs/block_contract.md) and return its summary."""
    step_file = tmp.parent / f"{tmp.name}.step.json"
    step_file.write_text(json.dumps({**step, "out_dir": str(tmp)}))
    try:
        _run(context, script, step_file, extra_env=extra_env)
    finally:
        step_file.unlink(missing_ok=True)
    return json.loads((tmp / "provenance.json").read_text()).get("summary", {})


def _meta(v):
    """A metadata value Dagster can show: numbers stay numbers (so they chart across
    partitions), everything else becomes short text."""
    if isinstance(v, bool) or v is None:
        return str(v)
    if isinstance(v, (int, float)):
        return v
    return v if isinstance(v, str) and len(v) < 2000 else json.dumps(v, default=str)[:2000]


def _provenance(done: dict, reused: bool, path: str, identity: str) -> dict:
    """What every materialization records about where its artifact came from."""
    return {**{k: _meta(v) for k, v in done["summary"].items()},
            "reused": reused, "artifact": path, "identity": identity,
            "built_by_run": done.get("run_id", "")[:8], "build_s": done.get("seconds")}


# --------------------------------------------------------------------------- #
# input steps and the reference
# --------------------------------------------------------------------------- #
def _input_asset(entry: dict):
    @dg.asset(key=dg.AssetKey(entry["key"]), group_name=GROUP, code_version=entry["identity"],
              deps=[dg.AssetKey(k) for k in entry["deps"]],
              description=f"{entry['block']} ({entry['kind']}): {entry['name']}"
                          + (f". Inserted because {entry['reason']}" if entry.get("reason") else ""),
              op_tags=_pod(entry["image"], entry["resources"]))
    def _asset(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        def build(tmp: Path) -> dict:
            step = {**entry["step"], "inputs": {k: str(ART / v) for k, v in entry["input_paths"].items()}}
            email = context.run.tags.get(TAG_EMAIL, "")
            return _run_step(context, entry["code"], step, tmp,
                             {"BENCH_LFPS_EMAIL": email} if email else None)
        done, reused = _materialize(context, entry["path"], build)
        return dg.MaterializeResult(metadata=_provenance(done, reused, entry["path"], entry["identity"]))
    return _asset


def _reference_asset(ref: dict):
    @dg.asset(key=dg.AssetKey(ref["key"]), group_name=GROUP, code_version=ref["identity"],
              description="The observed final perimeter, rasterized onto the case grid.",
              op_tags=_pod(ref["image"], ref["resources"]))
    def _asset(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        def build(tmp: Path) -> dict:
            src = tmp.parent / f"{tmp.name}.source.geojson"
            src.write_text(REFERENCE_GEOJSON)
            try:
                return _run_step(context, ref["code"], {**ref["step"], "inputs": {"file": str(src)}}, tmp)
            finally:
                src.unlink(missing_ok=True)
        done, reused = _materialize(context, ref["path"], build)
        return dg.MaterializeResult(metadata=_provenance(done, reused, ref["path"], ref["identity"]))
    return _asset


# --------------------------------------------------------------------------- #
# predictions (one partition per run), scores, report
# --------------------------------------------------------------------------- #
# the last step of every input branch: what predictions depend on
TAIL_KEYS = [e["key"] for e in PLAN["inputs"] if not any(e["key"] in o["deps"] for o in PLAN["inputs"])]
PRED_KEY = dg.AssetKey([ME, WF, "prediction"])
REF_KEY = dg.AssetKey(PLAN["reference"]["key"]) if PLAN["reference"] else None
MODEL_IMAGES = {r["image"] for r in PLAN["runs"].values()}
# One asset is one image. With a single real model that's fine; several models with
# different images will each need their own prediction asset.
assert len(MODEL_IMAGES) <= 1, f"models in different images need separate prediction assets: {MODEL_IMAGES}"


def _preview_md(pred_dir: Path) -> str | None:
    png = pred_dir / "preview.png"
    if not png.exists():
        return None
    return f"![prediction preview](data:image/png;base64,{base64.b64encode(png.read_bytes()).decode()})"


@dg.asset(key=PRED_KEY, group_name=GROUP, partitions_def=RUNS_PART, deps=[dg.AssetKey(k) for k in TAIL_KEYS],
          description="One spread-model run per partition: model x params x input choices.",
          op_tags=_pod(next(iter(MODEL_IMAGES), "core"),
                       next(iter(PLAN["runs"].values()), {}).get("resources", {})))
def prediction(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    run = PLAN["runs"][context.partition_key]
    missing = [s for s, p in run["input_paths"].items() if not _done(p)]
    if missing:
        raise dg.Failure(f"inputs not built yet for slots {missing}: run {ME}_{WF}_inputs_job first")

    def build(tmp: Path) -> dict:
        (tmp / "run.json").write_text(json.dumps(run["run_json"]))
        _run(context, run["code"], tmp)
        pred = tmp / "prediction"
        # drawn by the framework, not the model, so every model's preview looks the same
        try:
            _run(context, "previews.py", pred, run["params"].get("duration_min", 0) or 0)
        except dg.Failure as e:
            context.log.warning(f"preview failed (the prediction is kept): {e.metadata}")
        return json.loads((pred / "summary.json").read_text())

    done, reused = _materialize(context, run["path"], build)
    md = _provenance(done, reused, run["path"], run["identity"])
    if preview := _preview_md(ART / run["path"] / "prediction"):
        md["preview"] = dg.MetadataValue.md(preview)
    return dg.MaterializeResult(metadata={
        **md, "model": run["model"], "image": IMAGES[run["image"]], "run_id": run["run_id"],
        "params": json.dumps(run["params"]), "inputs": json.dumps(run["inputs"] or {"(one source per slot)": "-"})})


def _score_asset(metric: str):
    @dg.asset(key=dg.AssetKey([ME, WF, "score", metric]), group_name=GROUP, partitions_def=RUNS_PART,
              deps=[PRED_KEY] + ([REF_KEY] if REF_KEY else []),
              description=f"{metric}: the prediction vs the observed perimeter.",
              op_tags=_pod(PLAN["metrics"][metric]["image"], PLAN["metrics"][metric]["resources"]))
    def _asset(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        run = PLAN["runs"][context.partition_key]
        if not PLAN["reference"]:
            return dg.MaterializeResult(metadata={"skipped": "the workflow's reference file wasn't there "
                                                             "when it was compiled"})
        for need, path in [("prediction", run["path"]), ("reference", PLAN["reference"]["path"])]:
            if not _done(path):
                raise dg.Failure(f"{need} not built yet ({path})")

        def build(tmp: Path) -> dict:
            step = {"block": metric, "kind": "metric", "case": PLAN["case"], "params": {},
                    "inputs": {"prediction": str(ART / run["path"] / "prediction"),
                               "reference": str(ART / PLAN["reference"]["path"])}}
            _run_step(context, PLAN["metrics"][metric]["code"], step, tmp)
            return json.loads((tmp / "score.json").read_text())
        path = run["scores"][metric]
        done, reused = _materialize(context, path, build)
        return dg.MaterializeResult(metadata=_provenance(done, reused, path, path.rsplit("-", 1)[-1]))
    return _asset


@dg.asset(key=dg.AssetKey([ME, WF, "report"]), group_name=GROUP,
          deps=[dg.AssetKey([ME, WF, "score", m]) for m in PLAN["metrics"]],
          description="Every finished run's scores in one table (reads the artifact store).")
def report(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    rows = []
    for key in RUN_KEYS:
        run = PLAN["runs"][key]
        pred = _done(run["path"])
        row = {"run": key, "model": run["model"], "status": "done" if pred else "not run"}
        if pred:
            row["predicted_ha"] = pred["summary"].get("burned_area_ha")
        for m in PLAN["metrics"]:
            if s := _done(run["scores"][m]):
                row.update({k: v for k, v in s["summary"].items() if k in (m, "observed_ha")})
        rows.append(row)
    for s in PLAN["skipped"]:
        rows.append({"run": f"{s['model']} {s['inputs'] or ''}".strip(), "model": s["model"],
                     "status": f"skipped: {s['reason']}"})
    cols = list(dict.fromkeys(c for r in rows for c in r))
    table = "| " + " | ".join(cols) + " |\n|" + "---|" * len(cols) + "\n" + "\n".join(
        "| " + " | ".join(str(r.get(c, "")) for c in cols) + " |" for r in rows)
    md = {"runs": len(RUN_KEYS), "scored": sum("iou" in r for r in rows),
          "table": dg.MetadataValue.md(table), "rows": dg.MetadataValue.json(rows)}
    if scored := [r for r in rows if "iou" in r]:
        best = max(scored, key=lambda r: r["iou"])
        md.update({"best_run": best["run"], "best_iou": best["iou"]})
    return dg.MaterializeResult(metadata=md)


input_assets = [_input_asset(e) for e in PLAN["inputs"]]
reference_assets = [_reference_asset(PLAN["reference"])] if PLAN["reference"] else []
score_assets = [_score_asset(m) for m in PLAN["metrics"]]

defs = dg.Definitions(
    assets=[*input_assets, *reference_assets, prediction, *score_assets, report],
    jobs=[
        dg.define_asset_job(f"{ME}_{WF}_inputs_job",
                            selection=dg.AssetSelection.assets(*input_assets, *reference_assets)),
        dg.define_asset_job(f"{ME}_{WF}_runs_job",            # partitioned like prediction
                            selection=dg.AssetSelection.assets(prediction, *score_assets)),
        dg.define_asset_job(f"{ME}_{WF}_report_job", selection=dg.AssetSelection.assets(report)),
    ],
)
